            if (itemId === 'Straight' || itemId === 'Orthogonal' || itemId === 'Bezier') {
                connector.type = itemId;
            }
            else if (itemId === 'Identifying' || itemId === 'NonIdentifying') {
                erConnector.relationship = itemId;
            }
            else if (itemId === 'One' || itemId === 'Many' || itemId === 'OneAndOnlyOne'
                || itemId === 'ZeroOrOne' || itemId === 'ZeroOrMany' || itemId === 'OneOrMany') {
                erConnector.sourceMultiplicity.type = args.item.text;
            }
            else if (itemId === 'One_t' || itemId === 'Many_t' || itemId === 'OneAndOnlyOne_t'
                || itemId === 'ZeroOrOne_t' || itemId === 'ZeroOrMany_t' || itemId === 'OneOrMany_t') {
                erConnector.targetMultiplicity.type = args.item.text;
            }
            diagramInstance.dataBind();
        }
    }
    contextMenuOpen(args) {
        let hiddenId = [];
        if (args.element.className !== 'e-menu-parent e-ul ') {
            hiddenId = ['ConnectorType', 'Relationship', 'Source_Multiplicity', 'Target_Multiplicity'];
        }
        if (diagramInstance.selectedItems.connectors[0] instanceof Connector) {
            hiddenId = [];
        }
        args.hiddenItems = hiddenId; // Set the hidden menu items based on the logic above
    }
    render() {
        return (<div className="control-pane diagram-ERDiagram">
                <style>{SAMPLE_CSS}</style>
                <div className="control-section">
                    <div style={{ width: "100%" }}>
                        <div className="sb-mobile-palette-bar">
                            <div id="palette-icon" style={{ float: "right" }} className="e-ddb-icons1 e-toggle-palette"></div>
                        </div>
                        <div id="palette-space" className="sb-mobile-palette">
                            <SymbolPaletteComponent id="symbolpalette" ref={(palette) => (paletteInstance = palette)} palettes={erPalettes} width="100%" height="560px" symbolWidth={70} symbolHeight={70} enableAnimation={false} symbolMargin={{ left: 8, right: 8, top: 8, bottom: 8 }}>
                                <Inject services={[ErDiagrams]}/>
                            </SymbolPaletteComponent>
                        </div>
                        <div id="diagram-space" className="sb-mobile-diagram">
                            <DiagramComponent id="diagram" ref={(diagram) => (diagramInstance = diagram)} width={'100%'} height={'560px'} nodes={nodes} connectors={connectors} constraints={DiagramConstraints.Default | DiagramConstraints.LineRouting | DiagramConstraints.AvoidLineOverlapping} tool={DiagramTools.SingleSelect} snapSettings={{ constraints: SnapConstraints.None }} selectedItems={{ userHandles: [] }} getConnectorDefaults={(connector) => {
                connector.cornerRadius = 10;
                connector.type = 'Orthogonal';
                connector.constraints = ConnectorConstraints.Default;
                return connector;
            }} onUserHandleMouseDown={this.onUserHandleMouseDown} selectionChange={this.onSelectionChange} created={() => {
                // Fit the diagram to the page on creation.
                if (diagramInstance) {
                    this.diagramCreated = true;
                    diagramInstance.fitToPage();
                }
            }} load={() => {
                if (this.diagramCreated) {
                    setTimeout(() => diagramInstance.fitToPage(), 10);
                }
            }} contextMenuSettings={contextMenu} contextMenuClick={this.contextMenuClick} contextMenuOpen={this.contextMenuOpen}>
                                <Inject services={[DataBinding, UndoRedo, LineRouting, AvoidLineOverlapping, ErDiagrams, DiagramContextMenu]}/>
                            </DiagramComponent>
                        </div>
                    </div>
                </div>

            </div>);
    }
}

